"""Materialize the reviewed Chapter 5 reconstruction from immutable source witnesses.

This helper exists because the connected GitHub environment used for the bilingual pass
could review and commit text but could not execute the repository-wide local validation
suite. It verifies source hashes before writing Chapter 5 edit/alignment data, then calls
the repository's normal generators. Delete this helper once Chapter 5 is fully accepted
if it is no longer useful.
"""
from pathlib import Path
import hashlib
import json
import subprocess
import sys
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
NS = {'h': 'http://www.w3.org/1999/xhtml'}
MTL = ROOT / 'source/chapters/chapter-005.xhtml'
KOREAN = ROOT / 'source/korean/chapters/005.txt'
MTL_SHA = '7ba389ee1e36d3b0beedf8c0dded8e6d863e6647a59fab9b716ec854630f53bd'
KOREAN_SHA = '65c416b6d8a09534b0a2bf4eed602cc91d3b47ed80a0e1e8f536034be1bd6ee9'

FINAL = ['“You. I don’t like you. Come with me.”','“Come with me.”','“Come with me.”','The nine-year-old Baskerville triplets—Highbro, Middlebro, and Lowbro—were pestering him.','“…”','Eight-year-old Vikir remained silent, lost in thought.','Before his regression, meeting them as a child had been as terrifying as meeting death itself.','Decades later, they had even been involved in his execution.','More importantly, within a decade they would grow into exceptional warriors known as the Trident of Baskerville—or Hugo Le Baskerville’s Trident.','They would become rising stars who amassed great military achievements for the Baskerville family.','Which was precisely why he needed to crush them while they were still buds.','So that one day he could devour the Baskerville family itself.','“Waaah… You’re scaring me.”','Was this the right approach?','Vikir looked up at them and whimpered like a frightened child.','Then, still sniffling, he spoke to the arrogant triplets.','“Why don’t we go somewhere no one else is around?”','The triplets snickered.','“So you at least know what honor is.”','“Yeah.”','“Yeah.”','Even the triplets knew better than to beat someone where too many eyes could see.','They twisted Vikir’s arms, covered his mouth, and hauled him somewhere secluded.','Fang Castle was an old fortress built in an ancient architectural style, full of secluded corners and hidden spaces.','They crossed a half-flooded cellar entrance, passed an abandoned food storeroom and unrepaired cracks, then climbed a spiral staircase.','At the end of an unused corridor, they dragged Vikir into a secluded room.','Highbro, the leader, grinned.','“Make a sound and you might lose a body part. Well, if you get to the infirmary quickly enough, they can probably reattach it.”','“They can put it back on.”','“Put it back on.”','Watching a nine-year-old draw a dagger from his waist and smile so darkly, it was hard to believe he was only nine.','Were children simply more cruel?','Children could laugh as they tore the heads or wings off insects, then crushed them underfoot.','If ordinary children could be that cruel, the children of Baskerville were in a league of their own.','The three little demons closed in around Vikir.','“I heard you stayed submerged in the River Styx for seven minutes. We laughed for ages when the nanny bragged about it.”','“We laughed.”','“We laughed.”','Highbro jerked his chin toward Lowbro, the youngest beside him.','Lowbro grinned, nodded, moved behind Vikir, and clamped both hands over his nose and mouth.','Highbro watched Vikir with a nasty smile.','“Seven minutes? Big deal. Last three minutes and I’ll wager a finger.”','“I’m in!”','“Me too!”','Lowbro pressed harder over Vikir’s nose and mouth.','There was an almost innocent malice in the way his hands clamped down, as though he meant to deny Vikir even a thread of air.','Highbro and Middlebro held Vikir’s arms tight, smiling as they waited to pin him down if he struggled.','…But—','“…?”','“…?”','“…?”','The triplets exchanged puzzled looks.','Vikir simply stood there without moving, calmly watching them.','“Heh. Planning to hold out? You’ve got guts. Let’s see how long you last.”','“Let’s see.”','“Let’s see.”','The three tightened their grip.','One minute passed.','Without even using mana, a child his age should already have been desperate for breath.','“…”','Vikir remained exactly as he had been, calm-eyed and still.','“…You’re holding out pretty well, brat.”','“Brat.”','“Brat.”','The triplets kept squeezing, not noticing the smiles slowly disappearing from their faces.','Two minutes passed.','They grew quieter.','Time seemed to stretch endlessly around the motionless Vikir.','“…What’s wrong with this kid? Is he not breathing?”','“Isn’t he?”','“No way!”','Lowbro shook his head. No—Vikir’s breathing was definitely being blocked.','Three minutes.','Four minutes.','Five minutes.','Six minutes.','Seven minutes.','Eight minutes.','Nine minutes.','Ten minutes.','Vikir still hadn’t moved.','A chilling silence filled the room.','By then, the backs of the three bullies were drenched in cold sweat.','Ten minutes sounded short—until you actually counted all six hundred seconds.','All the while, Vikir watched them without so much as a blink, perfectly calm.','The room was as silent as a grave.','Finally—','Highbro forced a smile and motioned to Lowbro.','“…Tch. This isn’t fun anymore. Let the bastard go.”','“Let him go.”','“Let him go.”','Just as Lowbro started to pull his hand away from Vikir’s mouth—','“Aaaagh!?”','A scream burst out.','It wasn’t Vikir gasping or struggling.','Blood spurted from Lowbro’s index finger.','“…Ptooey.”','Vikir chewed whatever was in his mouth a few more times, then spat it out.','He gave the triplets a contemptuous smile.','“You were willing to wager a finger, weren’t you?”','Vikir grinned, blood coating his mouth.','All three triplets went pale.','A moment later, Highbro shouted through clenched teeth.','“…Hmph! So what? I’m not scared at all!”','“…I’m not scared!”','“…I’m scared!”','The last line slipped out before its speaker could stop it.','Highbro and Middlebro turned. Lowbro held up his hand and whimpered.','“My finger! He bit it off!”','The triplets’ rhythm immediately fell apart.','Baskerville children were used to seeing blood.','But it was different when the torn flesh and broken bone belonged to them.','The three who had always moved together like the prongs of a trident began to come apart.','Highbro, the eldest, tried to calm Lowbro, the youngest.','“Calm down, bro. We’ll go to the infirmary and have a priest reattach your finger.”','“Yeah. Let’s go.”','“Uwaaah… okay. Hurry!”','Middlebro hoisted Lowbro onto his back.','Highbro hurried to the door and pulled it open.','“Who said you could leave?”','Vikir was already blocking the doorway.','Highbro’s face twisted.','“You…”','That twisted expression never had a chance to straighten.','Crack!','Vikir’s fist slammed into him, shattering his nose and teeth.','Highbro collapsed to the floor, clutching his face.','Crunch!','Before Middlebro could even react, Vikir’s follow-up kick dislocated his jaw.','“Ghk!?”','“Ugh—”','“Waaah…”','The three brothers screamed, groaned, and sobbed in three different voices.','Vikir sat down calmly in front of the door.','“If you don’t get proper treatment within an hour, some of those injuries will stay with you for life.”','“…”','“But judging from the three of you, I don’t think any of you are leaving this room today.”','“…”','“Whenever the wind blows and the rain falls, whenever your teeth, jaw, or fingers ache, remember today.”','The triplets glared at Vikir as though they wanted to kill him.','Nine years of Baskerville upbringing had done nothing to dull their vicious tempers.','‘…Still, they’re only children.’','Vikir smiled faintly.','Once they had been beaten enough, no one dared talk back.','If someone still talked back after a beating, the only question was whether they had been beaten hard enough.','That was Hugo Le Baskerville’s philosophy of child-rearing—and the code of conduct of the entire Baskerville family.','“Aagh!”','Highbro, the eldest, screwed up his courage and charged again, short sword in hand.','But—','Thunk!','Highbro’s short sword struck Vikir squarely, yet failed to draw a single drop of blood.','“…What?”','Highbro stared blankly.','The spot where the blade touched Vikir’s chest flashed black for an instant, then returned to its normal flesh tone.','The protection of the River Styx.','At just eight years old, Vikir’s body had already become impervious to blades.','Crack!','The sound resembled the earlier impact of steel against flesh.','The result was nothing alike.','Highbro collapsed again as the rest of his teeth shattered.','Two punches. That was all it had taken.','Crunch… crack… grind—','Tears, snot, saliva, blood, bubbles, and broken teeth churned wetly inside his mouth.','Vikir’s shadow fell over the three brothers as they trembled and clutched their wounds.','Clang!','A dagger landed in the middle of the triplets.','None of them moved to pick it up.','Instinct told them why.','‘Touch that, and he’ll beat us even worse.’','The triplets knelt on the floor, heads bowed, bleeding, crying, drooling, and sweating cold.','All three had wet themselves in fear.','At that moment—','Vikir spoke.','“Only one of you three gets to leave this room alive.”','Hope flickered across the triplets’ faces, and their expressions changed instantly.','“Who?”','“Who?”','“Who?”','Vikir’s answer was simple.','“That’s for you brothers to decide.”','All three pairs of eyes snapped toward the dagger in the center of the room.','Rip—','The Trident of Baskerville began to split from within.']

SPECIFIC_REASONS = {9:"Clarify the future Trident title while preserving the chapter's decade-later perspective.",16:'Repair the broken MTL sentence and preserve Vikir as the speaker after his feigned crying.',24:'Retain the established Fang Castle name and recast the location description after Korean comparison.',26:"Restore the unused corridor and secluded room; remove the MTL's nonsensical 'bikinis' corruption.",39:'Keep Lowbro as the youngest; Korean mislabels him despite surrounding continuity and supporting character references.',40:"Preserve Lowbro as the brother who covers Vikir's nose and mouth.",42:"Render Highbro's wager idiomatically as staking a finger; later dialogue and injury pay off the wager.",59:'Clarify that Vikir is not using mana and should physiologically be short of breath.',72:'Keep Lowbro as the restraining actor based on uninterrupted action and supporting synopsis.',84:"Restore the Korean's six hundred seconds for ten minutes; reject MTL's 1-to-60 corruption.",85:"Restore Korean's unblinking calm; MTL's calm blinking contradicts the point of the sentence.",92:'Keep Lowbro releasing Vikir; Korean momentarily switches to Highbro despite the established restraint.',100:'Render the finger-wager callback naturally and in the singular.',109:"Use bitten-off finger, consistent with the MTL event, reattachment dialogue, and supporting synopsis; Korean's broken wording conflicts with the scene.",120:"Use leave; the brothers are opening the door to exit, while the Korean line's enter wording is contextually corrupted.",135:"Preserve the one-hour treatment deadline without the MTL's pronoun error.",144:"Restore the first half of Hugo's child-rearing maxim from the Korean witness.",145:"Restore the second half of Hugo's child-rearing maxim from the Korean witness.",146:"Preserve attribution of the maxim to Hugo Le Baskerville and the family's code of conduct.",148:"Integrate Korean line 153's short-sword detail into the matching Highbro charge paragraph without adding or deleting an MTL paragraph.",156:'Render the demonstrated Styx protection as imperviousness to blades in this scene; do not generalize it to all attacks.',162:'Replace opaque MTL sound-token romanization with contextual impact/grinding sound prose.',174:"Preserve Vikir's explicit threat that only one of the three may leave alive.",183:'Preserve the exact endpoint: the Trident begins splitting from within; do not import Chapter 6 consequences.'}

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def main():
    mtl_bytes = MTL.read_bytes()
    korean_bytes = KOREAN.read_bytes()
    if sha(mtl_bytes) != MTL_SHA:
        raise SystemExit('Chapter 5 MTL checksum mismatch; refusing to materialize edits')
    if sha(korean_bytes) != KOREAN_SHA:
        raise SystemExit('Chapter 5 Korean checksum mismatch; refusing to materialize alignment')
    doc = ET.fromstring(mtl_bytes)
    body = doc.find('.//h:div[@class="chapter-content"]', NS)
    originals = [''.join(p.itertext()) for p in body.findall('.//h:p', NS)]
    if len(originals) != 183 or len(FINAL) != 183:
        raise SystemExit(f'Expected 183 paragraphs, got source={len(originals)} final={len(FINAL)}')
    def kmap(p):
        if p <= 147: return [p + 4]
        if p == 148: return [152, 153]
        return [p + 5]
    edits=[]
    for number,(old,new) in enumerate(zip(originals,FINAL),1):
        if old == new: continue
        nums=kmap(number)
        default='Repair English tense, phrasing, punctuation or perspective after comparing Korean '+('lines ' if len(nums)>1 else 'line ')+', '.join(map(str,nums))+'.'
        edits.append([number,new,SPECIFIC_REASONS.get(number,default)])
    spec={'chapter':5,'source':'source/chapters/chapter-005.xhtml','source_sha256':MTL_SHA,'expected_paragraphs':183,'notice':'New reconstruction, not recovered production. Explicit source adjudications and limitations are recorded in editorial/reviews/chapter-0005.md.','korean_alignment':'editorial/korean-alignment/chapter-0005.json','scene_breaks_after':[],'edits':edits}
    lines=korean_bytes.decode('utf-8-sig').splitlines()
    if len(lines) != 188: raise SystemExit(f'Expected 188 Korean physical lines, got {len(lines)}')
    specific_compare={24:'Retain Fang Castle from the established English continuity; Korean calls it the young-wolves fortress, so do not invent a second location.',26:"Restore the unused-corridor room from Korean; reject the MTL's nonsensical 'bikinis' corruption.",39:'Keep Lowbro as the youngest; the Korean line mislabels him as eldest, conflicting with scene continuity and supporting character references.',42:'Render the wager as staking a finger rather than literally cutting one off in advance; later action pays off the threat.',59:'Clarify that Vikir is not using mana while holding his breath.',72:'Keep Lowbro as the restraining actor based on the uninterrupted action and supporting synopsis.',84:'Use six hundred seconds for the ten-minute interval; Korean explicitly gives 600 while MTL corrupts this to 1–60.',85:"Restore Korean's unblinking calm rather than MTL's contradictory calm blinking.",92:'Keep Lowbro releasing Vikir; Korean momentarily switches to Highbro despite the established restraint.',100:"Render the callback to Highbro's wager naturally and preserve finger singular.",109:"Use bitten-off finger, consistent with the MTL event, visible wound sequence, and supporting synopsis; Korean's 'broken' wording conflicts with reattachment context.",120:"Use leave rather than Korean's machine-like enter wording; the brothers are at the door trying to exit.",144:"Restore the first half of Hugo's child-rearing maxim from Korean.",145:"Restore the second half of Hugo's child-rearing maxim from Korean.",146:"Keep the maxim attributed to Hugo Le Baskerville and the Baskerville family code.",148:"Merge Korean's separate short-sword detail into the matching Highbro charge paragraph without adding a new MTL paragraph.",156:"Render the demonstrated Styx protection as blade imperviousness in this scene; do not generalize it to all attacks.",174:"Preserve Vikir's explicit threat that only one of the three may leave alive.",183:'Preserve the exact chapter endpoint: the Trident begins splitting from within; do not import Chapter 6 consequences.'}
    alignment={'chapter':5,'korean_source':'source/korean/chapters/005.txt','korean_sha256':KOREAN_SHA,'mtl_source':'source/chapters/chapter-005.xhtml','mtl_sha256':MTL_SHA,'line_numbering':'One-based physical UTF-8 splitlines; original bytes unchanged.','line_count':188,'paragraphs':[],'non_body_lines':[{'line':1,'disposition':'Repeated title/edition heading.'},{'line':2,'disposition':'Repeated title/edition heading.'},{'line':3,'disposition':'Repeated title/edition heading.'},{'line':4,'disposition':'Repeated title/edition heading.'}],'shared_lines':[]}
    for p in range(1,184):
        nums=kmap(p)
        alignment['paragraphs'].append({'mtl_paragraph':p,'korean_lines':nums,'line_text_sha256':[sha(lines[n-1].encode()) for n in nums],'comparison':specific_compare.get(p,'Compared corresponding meaning, event and speaker; source decisions in editorial/reviews/chapter-0005.md.')})
    (ROOT/'editorial/edits').mkdir(parents=True,exist_ok=True)
    (ROOT/'editorial/korean-alignment').mkdir(parents=True,exist_ok=True)
    (ROOT/'editorial/edits/chapter-0005.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (ROOT/'editorial/korean-alignment/chapter-0005.json').write_text(json.dumps(alignment,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    subprocess.run([sys.executable,str(ROOT/'tools/build_editorial_draft.py'),'5'],check=True)
    subprocess.run([sys.executable,str(ROOT/'tools/build_chapter_preview.py'),'5'],check=True)
    print(f'Chapter 5 materialized: {len(edits)} changed paragraphs; alignment covers {len(lines)} Korean lines.')

if __name__ == '__main__':
    main()
